const squadHasLeadershipIssues = `-- name: SquadHasLeadershipIssues :one
SELECT EXISTS (SELECT 1 FROM issue i JOIN issue r ON r.id=COALESCE(i.leadership_root_issue_id,i.id) AND r.workspace_id=i.workspace_id WHERE i.workspace_id=$1 AND r.leadership_squad_id=$2 AND issue_effective_status(i.workspace_id,i.status) NOT IN ('done','cancelled')) AS has_issues
`

type SquadHasLeadershipIssuesParams struct {
	WorkspaceID       pgtype.UUID `json:"workspace_id"`
	LeadershipSquadID pgtype.UUID `json:"leadership_squad_id"`
}

func (q *Queries) SquadHasLeadershipIssues(ctx context.Context, arg SquadHasLeadershipIssuesParams) (bool, error) {
	row := q.db.QueryRow(ctx, squadHasLeadershipIssues, arg.WorkspaceID, arg.LeadershipSquadID)
	var has_issues bool
	err := row.Scan(&has_issues)
	return has_issues, err
}

const withdrawLeadershipDeliveries = `-- name: WithdrawLeadershipDeliveries :exec
UPDATE agent_mailbox_message
SET delivery_status=CASE WHEN delivery_status='pending' THEN 'failed' ELSE delivery_status END,
 withdrawn_at=COALESCE(withdrawn_at,now()), updated_at=now(),
 last_error=CASE WHEN delivery_status='pending' THEN 'Task leadership handed off' ELSE last_error END
WHERE workspace_id= $1 AND issue_id= $2 AND recipient_agent_id= $3
 AND target_session_id IS NOT NULL AND kind IN ('issue_assignment','comment_mention','issue_wakeup')
 AND delivery_status IN ('pending','leased','unknown') AND withdrawn_at IS NULL
`

type WithdrawLeadershipDeliveriesParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	IssueID     pgtype.UUID `json:"issue_id"`
	AgentID     pgtype.UUID `json:"agent_id"`
}

func (q *Queries) WithdrawLeadershipDeliveries(ctx context.Context, arg WithdrawLeadershipDeliveriesParams) error {
	_, err := q.db.Exec(ctx, withdrawLeadershipDeliveries, arg.WorkspaceID, arg.IssueID, arg.AgentID)
	return err
}
